let sparkleKeySettings = {
    enabled: true,
    color: '#000000',
    tolerance: 25,
    smoothness: 15,
    bloomEnabled: true,
    bloomBlendMode: 'screen',
    bloomStrength: 1.2,
    bloomRadius: 15,
    bloomOpacity: 1.0,
    bloomColor: '#ffffff'
};
window.sparkleKeySettings = sparkleKeySettings;

const cachedSpriteImages = {};
const cachedKeyedCanvases = { '2': [], '3': [], '4': [] };
const cachedFrameDataUrls = { '2': [], '3': [], '4': [] };

function preloadSparklePresets() {
    ['2', '3', '4'].forEach(id => {
        const preset = SPARKLE_PRESETS[id];
        if (!preset || !preset.spritesheet) return;
        const img = new Image();
        img.src = preset.spritesheet;
        img.onload = () => {
            cachedSpriteImages[id] = img;
            processKeyedFrames(id);
            drawSparkles();
        };
        img.onerror = () => {
            console.warn("Nie udało się załadować spritesheet dla błysku: " + preset.name);
        };
    });
}

function processKeyedFrames(presetId) {
    const preset = SPARKLE_PRESETS[presetId];
    if (!preset || !preset.isAnimated) return;
    const sheetImg = cachedSpriteImages[presetId];
    if (!sheetImg || !sheetImg.complete) return;

    cachedKeyedCanvases[presetId] = [];
    cachedFrameDataUrls[presetId] = [];

    const cols = preset.cols || 8;
    const size = Math.round((sheetImg.naturalWidth || 2048) / cols);
    const count = preset.frameCount;

    let hex = (sparkleKeySettings.color || '#000000').replace('#', '');
    if (hex.length === 3) hex = hex.split('').map(c => c + c).join('');
    const kr = parseInt(hex.substring(0, 2), 16) || 0;
    const kg = parseInt(hex.substring(2, 4), 16) || 0;
    const kb = parseInt(hex.substring(4, 6), 16) || 0;

    const tolDist = (sparkleKeySettings.tolerance / 100) * 441.67;
    const smoothDist = (sparkleKeySettings.smoothness / 100) * 441.67;
    const keyEnabled = sparkleKeySettings.enabled;

    for (let f = 0; f < count; f++) {
        const col = f % cols;
        const row = Math.floor(f / cols);
        const sx = col * size;
        const sy = row * size;

        const cvs = document.createElement('canvas');
        cvs.width = size;
        cvs.height = size;
        const ctx = cvs.getContext('2d');
        ctx.drawImage(sheetImg, sx, sy, size, size, 0, 0, size, size);

        if (keyEnabled) {
            try {
                const imgData = ctx.getImageData(0, 0, size, size);
                const data = imgData.data;
                for (let i = 0; i < data.length; i += 4) {
                    const r = data[i], g = data[i+1], b = data[i+2];
                    const dr = r - kr, dg = g - kg, db = b - kb;
                    const dist = Math.sqrt(dr * dr + dg * dg + db * db);

                    if (dist <= tolDist) {
                        data[i+3] = 0;
                    } else if (dist < tolDist + smoothDist && smoothDist > 0) {
                        data[i+3] = Math.round(data[i+3] * ((dist - tolDist) / smoothDist));
                    }
                }
                ctx.putImageData(imgData, 0, 0);
            } catch (err) {
                // Ignore security error if tainted
            }
        }

        cachedKeyedCanvases[presetId].push(cvs);
        try {
            cachedFrameDataUrls[presetId].push(cvs.toDataURL('image/png'));
        } catch (e) {
            cachedFrameDataUrls[presetId].push('');
        }
    }
}

let keyUpdateTimeout = null;
function scheduleKeyUpdate() {
    clearTimeout(keyUpdateTimeout);
    keyUpdateTimeout = setTimeout(() => {
        ['2', '3', '4'].forEach(id => processKeyedFrames(id));
        drawSparkles();
    }, 30);
}

function getSparkleFrameCanvas(presetId, frameIndex) {
    if (presetId === '1' || !SPARKLE_PRESETS[presetId] || !SPARKLE_PRESETS[presetId].isAnimated) {
        return null;
    }
    const frames = cachedKeyedCanvases[presetId];
    if (!frames || frames.length === 0) return null;
    const idx = Math.max(0, Math.min(frames.length - 1, frameIndex % frames.length));
    return frames[idx];
}

function getSparkleFrameDataUrl(presetId, frameIndex) {
    if (presetId === '1' || !SPARKLE_PRESETS[presetId] || !SPARKLE_PRESETS[presetId].isAnimated) {
        return getCurrentSparkleTextureSrc();
    }
    const urls = cachedFrameDataUrls[presetId];
    if (!urls || urls.length === 0 || !urls[0]) return getCurrentSparkleTextureSrc();
    const idx = Math.max(0, Math.min(urls.length - 1, frameIndex % urls.length));
    return urls[idx];
}

