// TIMELINE EDITOR IMPLEMENTATION
function initTimelineRuler() {
    if (!timelineRuler) return;
    
    const rulerWidth = Math.max(100, (state.totalFrames || 240) * state.pixelsPerFrame);
    timelineRuler.width = rulerWidth;
    timelineRuler.height = 20;
    timelineRuler.style.width = `${rulerWidth}px`;
    
    const rulerContentArea = document.getElementById('ruler-content-area');
    if (rulerContentArea) {
        rulerContentArea.style.width = `${rulerWidth}px`;
    }
    
    const ctx = timelineRuler.getContext('2d');
    ctx.fillStyle = '#0f1422';
    ctx.fillRect(0, 0, rulerWidth, 20);
    
    ctx.fillStyle = '#94a3b8';
    ctx.font = '9px monospace';
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.12)';
    ctx.lineWidth = 1;
    
    const fps = state.fps || 30;
    for (let f = 0; f < state.totalFrames; f++) {
        const x = f * state.pixelsPerFrame;
        ctx.beginPath();
        if (f % fps === 0) {
            // Seconds ticks
            ctx.moveTo(x, 0);
            ctx.lineTo(x, 12);
            ctx.fillStyle = '#f8fafc';
            ctx.fillText(`${f / fps}s`, x + 3, 10);
        } else if (f % 10 === 0) {
            // 10 frame ticks
            ctx.moveTo(x, 0);
            ctx.lineTo(x, 6);
            ctx.fillStyle = '#64748b';
            ctx.fillText(f.toString(), x + 2, 18);
        } else if (f % 5 === 0) {
            // 5 frame ticks
            ctx.moveTo(x, 0);
            ctx.lineTo(x, 4);
        }
        ctx.stroke();
    }
    
    // Set explicit widths on all track content elements so horizontal scroll reflects full duration
    document.querySelectorAll('.track-content').forEach(tc => {
        tc.style.width = `${rulerWidth}px`;
    });
    
    document.querySelectorAll('.timeline-track-row, .timeline-ruler-row').forEach(row => {
        row.style.minWidth = `${rulerWidth + 72}px`;
    });
}

function updatePlayhead() {
    if (!timelinePlayhead) return;
    
    let currentFrame = 0;
    let currentTimeSec = 0;
    if (state.isVideo && previewVideo) {
        currentFrame = Math.round(previewVideo.currentTime * state.fps);
        currentTimeSec = previewVideo.currentTime;
    } else {
        currentFrame = state.currentFrame || 0;
        currentTimeSec = currentFrame / (state.fps || 30);
    }
    state.currentFrame = currentFrame;
    const x = currentFrame * state.pixelsPerFrame;
    
    timelinePlayhead.style.left = `${x}px`;
    if (timelineTimeInfo) {
        timelineTimeInfo.textContent = `Klatka: ${currentFrame} / ${state.totalFrames} | ${currentTimeSec.toFixed(2)}s`;
    }
    
    // Autoscroll timeline container during playback if playhead approaches or passes edge
    const tlScrollBox = document.getElementById('timeline-scroll-container');
    if (tlScrollBox && (state.imageAnimInterval || (previewVideo && !previewVideo.paused))) {
        const visibleW = tlScrollBox.clientWidth - 72;
        const curScroll = tlScrollBox.scrollLeft;
        if (x > curScroll + visibleW - 30) {
            tlScrollBox.scrollLeft = x - 50;
        } else if (x < curScroll) {
            tlScrollBox.scrollLeft = Math.max(0, x - 50);
        }
    }
    
    // Aktualizuj klasę in-range na segmentach osi czasu
    document.querySelectorAll('.timeline-segment').forEach(seg => {
        const clipId = seg.getAttribute('data-clip-id');
        const clip = (state.clips || []).find(c => c.id === clipId);
        if (clip) {
            const inRange = (currentFrame >= clip.start_frame && currentFrame <= clip.end_frame);
            seg.classList.toggle('in-range', inRange);
        }
    });
    
    // Sync drawSparkles state (aktywuj klatki błysków)
    drawSparkles();
}


    // Redraw preview sparkles when visual settings change
    if (typeof sparkleTextureSelect !== 'undefined' && sparkleTextureSelect) sparkleTextureSelect.addEventListener('change', drawSparkles);
    if (typeof sparkleSizeMinInput !== 'undefined' && sparkleSizeMinInput) sparkleSizeMinInput.addEventListener('input', drawSparkles);
    if (typeof sparkleSizeMaxInput !== 'undefined' && sparkleSizeMaxInput) sparkleSizeMaxInput.addEventListener('input', drawSparkles);
    if (typeof sparkleOpacitySlider !== 'undefined' && sparkleOpacitySlider) sparkleOpacitySlider.addEventListener('input', drawSparkles);
    if (typeof sparkleOpacityInput !== 'undefined' && sparkleOpacityInput) {
        sparkleOpacityInput.addEventListener('input', drawSparkles);
        sparkleOpacityInput.addEventListener('change', drawSparkles);
    }
    if (typeof sparkleBlendModeSelect !== 'undefined' && sparkleBlendModeSelect) sparkleBlendModeSelect.addEventListener('change', drawSparkles);
    if (typeof exportFormatSelect !== 'undefined' && exportFormatSelect) {
        exportFormatSelect.addEventListener('change', () => {
            const val = exportFormatSelect.value;
            let base = outputNameInput.value.replace(/\.(mp4|webm)$/i, '');
            if (val === 'webm') outputNameInput.value = base + '.webm';
            else if (val === 'mp4') outputNameInput.value = base + '.mp4';
        });
    }


function setupSparklePresetAndEffects() {
    preloadSparklePresets();

    const selectPreset = (presetId) => {
        state.selectedSparkleType = presetId.toString();
        if (sparklePresetSelect) sparklePresetSelect.value = state.selectedSparkleType;
        if (sparkleTextureSelect) sparkleTextureSelect.value = state.selectedSparkleType;

        btnSparklePresets.forEach(btn => {
            btn.classList.toggle('active', btn.getAttribute('data-preset') === state.selectedSparkleType);
        });

        // Istniejące błyski zachowują swój typ; tylko nowo dodawane otrzymają state.selectedSparkleType

        // Aktualizacja podpowiedzi wizualnych dla efektów
        const animParamsCard = document.getElementById('card-sparkle-animation-params');
        const animBadge = document.getElementById('sparkle-anim-badge');
        const animNotice = document.getElementById('sparkle-anim-notice');
        if (animParamsCard) {
            if (state.selectedSparkleType === '1') {
                animParamsCard.style.opacity = '1.0';
                if (animBadge) animBadge.textContent = 'Aktywne dla 1: blysk.png';
                if (animNotice) animNotice.style.display = 'block';
            } else {
                animParamsCard.style.opacity = '0.55';
                if (animBadge) animBadge.textContent = 'Nieaktywne dla wideo (2, 3, 4)';
                if (animNotice) animNotice.style.display = 'block';
            }
        }

        drawSparkles();
        updateSparklesDisplay();
    };

    window.selectSparklePreset = selectPreset;

    if (sparklePresetSelect) {
        sparklePresetSelect.addEventListener('change', () => selectPreset(sparklePresetSelect.value));
    }
    if (sparkleTextureSelect) {
        sparkleTextureSelect.addEventListener('change', () => selectPreset(sparkleTextureSelect.value));
    }

    btnSparklePresets.forEach(btn => {
        btn.addEventListener('click', () => {
            const p = btn.getAttribute('data-preset');
            if (p) selectPreset(p);
        });
    });

    // Skróty klawiszowe 1, 2, 3, 4 do zmiany trybu błysku
    window.addEventListener('keydown', (e) => {
        const targetTag = e.target.tagName ? e.target.tagName.toLowerCase() : '';
        if (targetTag === 'input' || targetTag === 'textarea' || targetTag === 'select' || e.target.isContentEditable) {
            return;
        }

        if (['1', '2', '3', '4'].includes(e.key)) {
            e.preventDefault();
            selectPreset(e.key);
            const presetNames = {
                '1': 'Normalny (blysk.png)',
                '2': 'Animowany Snowdrop 01',
                '3': 'Animowany Błysk 01',
                '4': 'Animowana Śnieżynka 01'
            };
            logMessage(`Przełączono tryb błysku klawiszem [${e.key}]: ${presetNames[e.key]}`, 'info');
        }
    });

    // Podpięcie suwaka szybkości animacji wideo
    const sparkleAnimSpeedSlider = document.getElementById('sparkle-anim-speed');
    const sparkleAnimSpeedVal = document.getElementById('sparkle-anim-speed-val');
    if (sparkleAnimSpeedSlider && sparkleAnimSpeedVal) {
        sparkleAnimSpeedSlider.addEventListener('input', () => {
            const val = parseFloat(sparkleAnimSpeedSlider.value) || 1.0;
            state.sparkleAnimSpeed = val;
            sparkleAnimSpeedVal.textContent = `${val.toFixed(1)}x`;
            drawSparkles();
        });
    }

    // Podpięcie suwaków chromakey i bloom
    const setupChromaControls = () => {
        if (sparkleKeyEnableCheckbox) {
            sparkleKeyEnableCheckbox.addEventListener('change', () => {
                sparkleKeySettings.enabled = sparkleKeyEnableCheckbox.checked;
                scheduleKeyUpdate();
            });
        }
        if (sparkleKeyColorInput) {
            sparkleKeyColorInput.addEventListener('input', () => {
                sparkleKeySettings.color = sparkleKeyColorInput.value;
                if (sparkleKeyColorVal) sparkleKeyColorVal.textContent = sparkleKeyColorInput.value;
                scheduleKeyUpdate();
            });
        }
        if (sparkleKeyToleranceSlider) {
            sparkleKeyToleranceSlider.addEventListener('input', () => {
                sparkleKeySettings.tolerance = parseInt(sparkleKeyToleranceSlider.value) || 25;
                if (sparkleKeyToleranceVal) sparkleKeyToleranceVal.textContent = `${sparkleKeySettings.tolerance}%`;
                scheduleKeyUpdate();
            });
        }
        if (sparkleKeySmoothnessSlider) {
            sparkleKeySmoothnessSlider.addEventListener('input', () => {
                sparkleKeySettings.smoothness = parseInt(sparkleKeySmoothnessSlider.value) || 15;
                if (sparkleKeySmoothnessVal) sparkleKeySmoothnessVal.textContent = `${sparkleKeySettings.smoothness}%`;
                scheduleKeyUpdate();
            });
        }
        if (sparkleBloomEnableCheckbox) {
            sparkleBloomEnableCheckbox.addEventListener('change', () => {
                sparkleKeySettings.bloomEnabled = sparkleBloomEnableCheckbox.checked;
                drawSparkles();
            });
        }
        if (sparkleBloomBlendModeSelect) {
            sparkleBloomBlendModeSelect.addEventListener('change', () => {
                sparkleKeySettings.bloomBlendMode = sparkleBloomBlendModeSelect.value;
                drawSparkles();
            });
        }
        if (sparkleBloomStrengthInput) {
            const onStrength = () => {
                sparkleKeySettings.bloomStrength = Math.max(0, parseFloat(sparkleBloomStrengthInput.value) || 0);
                drawSparkles();
            };
            sparkleBloomStrengthInput.addEventListener('input', onStrength);
            sparkleBloomStrengthInput.addEventListener('change', onStrength);
        }
        if (sparkleBloomRadiusInput) {
            const onRadius = () => {
                sparkleKeySettings.bloomRadius = Math.max(0, parseInt(sparkleBloomRadiusInput.value) || 0);
                drawSparkles();
            };
            sparkleBloomRadiusInput.addEventListener('input', onRadius);
            sparkleBloomRadiusInput.addEventListener('change', onRadius);
        }
        if (sparkleBloomOpacityInput) {
            const onOpacity = () => {
                let op = parseFloat(sparkleBloomOpacityInput.value);
                if (isNaN(op)) op = 1.0;
                sparkleKeySettings.bloomOpacity = Math.max(0, Math.min(1.0, op));
                drawSparkles();
            };
            sparkleBloomOpacityInput.addEventListener('input', onOpacity);
            sparkleBloomOpacityInput.addEventListener('change', onOpacity);
        }
        if (sparkleBloomColorInput) {
            sparkleBloomColorInput.addEventListener('input', () => {
                sparkleKeySettings.bloomColor = sparkleBloomColorInput.value;
                if (sparkleBloomColorVal) sparkleBloomColorVal.value = sparkleBloomColorInput.value;
                drawSparkles();
            });
        }
        if (sparkleBloomColorVal) {
            sparkleBloomColorVal.addEventListener('input', () => {
                let val = sparkleBloomColorVal.value.trim();
                if (val.startsWith('#') && (val.length === 4 || val.length === 7)) {
                    sparkleKeySettings.bloomColor = val;
                    if (sparkleBloomColorInput) sparkleBloomColorInput.value = val;
                    drawSparkles();
                }
            });
        }
    };
    setupChromaControls();
}

window.imagePlayInterval = null;

function setupTimeline() {
    if (!timelineRuler) return;
    
    let isScrubbing = false;
    
    const seekToPosition = (e) => {
        const rect = timelineRuler.getBoundingClientRect();
        // rect.left is viewport relative, so e.clientX - rect.left gives exact pixel coordinate on ruler canvas
        const clickX = e.clientX - rect.left;
        const frame = Math.max(0, Math.min(state.totalFrames - 1, Math.round(clickX / state.pixelsPerFrame)));
        state.currentFrame = frame;
        if (state.isVideo && previewVideo) {
            previewVideo.currentTime = frame / state.fps;
        }
        updatePlayhead();
    };
    
    timelineRuler.addEventListener('mousedown', (e) => {
        isScrubbing = true;
        seekToPosition(e);
    });

    const trackArea = document.getElementById('timeline-tracks');
    if (trackArea) {
        trackArea.addEventListener('mousedown', (e) => {
            if (e.target.closest('.timeline-segment') || e.target.closest('.track-info')) return;
            isScrubbing = true;
            seekToPosition(e);
        });
    }
    
    window.addEventListener('mousemove', (e) => {
        if (isScrubbing) seekToPosition(e);
    });
    
    window.addEventListener('mouseup', () => {
        isScrubbing = false;
    });
    
    // Enable smooth horizontal scrolling via mouse wheel anywhere over timeline
    const scrollContainer = document.getElementById('timeline-scroll-container');
    if (scrollContainer) {
        scrollContainer.addEventListener('wheel', (e) => {
            if (e.deltaY !== 0 && e.deltaX === 0) {
                e.preventDefault();
                scrollContainer.scrollLeft += e.deltaY;
            }
        }, { passive: false });
    }

    btnTimelinePlay.addEventListener('click', () => {
        if (state.isVideo && previewVideo) {
            if (previewVideo.paused) {
                previewVideo.play();
                btnTimelinePlay.textContent = '⏸';
            } else {
                previewVideo.pause();
                btnTimelinePlay.textContent = '▶';
            }
        } else {
            if (window.imagePlayInterval) {
                clearInterval(window.imagePlayInterval);
                window.imagePlayInterval = null;
                btnTimelinePlay.textContent = '▶';
                drawSparkles();
            } else {
                btnTimelinePlay.textContent = '⏸';
                const fps = state.fps || 30;
                window.imagePlayInterval = setInterval(() => {
                    state.currentFrame = ((state.currentFrame || 0) + 1) % (state.totalFrames || 240);
                    updatePlayhead();
                }, 1000 / fps);
            }
        }
    });
    
    previewVideo.addEventListener('play', () => {
        btnTimelinePlay.textContent = '⏸';
    });
    previewVideo.addEventListener('pause', () => {
        btnTimelinePlay.textContent = '▶';
        drawSparkles();
    });
    previewVideo.addEventListener('timeupdate', updatePlayhead);
    previewVideo.addEventListener('seeked', updatePlayhead);
    
    // Wire layer selector buttons
    btnLayers.forEach(btn => {
        btn.addEventListener('click', () => {
            btnLayers.forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            state.activeLayer = btn.getAttribute('data-layer');
        });
    });
}

function renderTimelineTracks() {
    const trackContent = document.getElementById('track-sparkles-content') || document.getElementById('track-small-content');
    if (!trackContent) return;
    
    syncClipsWithSparkles();
    trackContent.innerHTML = '';
    
    const currentFrame = state.isVideo 
        ? Math.round(previewVideo.currentTime * state.fps) 
        : (state.currentFrame || 0);
    
    state.clips.forEach((clip, cIdx) => {
        const container = trackContent;
        
        const start = Math.max(0, clip.start_frame || 0);
        const end = Math.min(state.totalFrames, Math.max(start + 1, clip.end_frame || state.totalFrames));
        
        const left = start * state.pixelsPerFrame;
        const width = Math.max(20, (end - start) * state.pixelsPerFrame);
        
        // Count sparkles in this clip
        const sparklesInClip = state.sparkles.filter(s => s.clip_id === clip.id);
        const count = sparklesInClip.length;
        if (count === 0) return;
        
        const isInRange = (start <= currentFrame && currentFrame <= end);
        
        const segment = document.createElement('div');
        segment.className = 'timeline-segment' + (isInRange ? ' in-range' : '');
        segment.style.left = `${left}px`;
        segment.style.width = `${width}px`;
        segment.setAttribute('data-clip-id', clip.id);
        
        segment.innerHTML = `
            <div class="segment-handle segment-handle-l" data-clip-id="${clip.id}" title="Przeciągnij, aby przedłużyć/skrócić do tyłu"></div>
            <div class="segment-title">
                <span>✨ Granica #${cIdx + 1}</span>
                <span class="segment-badge">${count} błysk. (${start}-${end})</span>
            </div>
            <button class="segment-delete-btn" data-clip-id="${clip.id}" title="Usuń tę granicę i jej błyski">✕</button>
            <div class="segment-handle segment-handle-r" data-clip-id="${clip.id}" title="Przeciągnij, aby przedłużyć/skrócić do przodu"></div>
        `;
        
        // Delete clip button
        const delBtn = segment.querySelector('.segment-delete-btn');
        if (delBtn) {
            delBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                state.sparkles = state.sparkles.filter(s => s.clip_id !== clip.id);
                cleanupEmptyClips();
                renderTimelineTracks();
                drawSparkles();
                updateSparklesDisplay();
                logMessage(`Usunięto granicę #${cIdx + 1} i jej ${count} błysków`, 'info');
            });
        }
        
        // Drag to move entire clip in time
        segment.addEventListener('mousedown', (e) => {
            if (e.target.classList.contains('segment-handle') || e.target.classList.contains('segment-delete-btn')) return;
            e.stopPropagation();
            
            document.querySelectorAll('.timeline-segment').forEach(s => s.classList.remove('selected'));
            segment.classList.add('selected');
            
            let startX = e.clientX;
            const origStart = clip.start_frame;
            const origEnd = clip.end_frame;
            const origDuration = origEnd - origStart;
            
            const onMouseMove = (moveEvt) => {
                const diffX = moveEvt.clientX - startX;
                const diffFrames = Math.round(diffX / state.pixelsPerFrame);
                
                let newStart = Math.max(0, Math.min(state.totalFrames - origDuration, origStart + diffFrames));
                let newEnd = newStart + origDuration;
                
                clip.start_frame = newStart;
                clip.end_frame = newEnd;
                
                state.sparkles.forEach(s => {
                    if (s.clip_id === clip.id) {
                        s.start_frame = newStart;
                        s.end_frame = newEnd;
                    }
                });
                
                segment.style.left = `${newStart * state.pixelsPerFrame}px`;
                segment.style.width = `${origDuration * state.pixelsPerFrame}px`;
                const badge = segment.querySelector('.segment-badge');
                if (badge) badge.textContent = `${count} błysk. (${newStart}-${newEnd})`;
                
                drawSparkles();
            };
            
            const onMouseUp = () => {
                window.removeEventListener('mousemove', onMouseMove);
                window.removeEventListener('mouseup', onMouseUp);
                renderTimelineTracks();
                drawSparkles();
            };
            
            window.addEventListener('mousemove', onMouseMove);
            window.addEventListener('mouseup', onMouseUp);
        });
        
        // Drag handles to extend/shorten backwards or forwards
        const leftHandle = segment.querySelector('.segment-handle-l');
        const rightHandle = segment.querySelector('.segment-handle-r');
        
        if (leftHandle) {
            leftHandle.addEventListener('mousedown', (e) => {
                e.stopPropagation();
                let startX = e.clientX;
                const origStart = clip.start_frame;
                const origEnd = clip.end_frame;
                
                const onMouseMove = (moveEvt) => {
                    const diffX = moveEvt.clientX - startX;
                    const diffFrames = Math.round(diffX / state.pixelsPerFrame);
                    
                    let newStart = Math.max(0, Math.min(origEnd - 1, origStart + diffFrames));
                    clip.start_frame = newStart;
                    
                    state.sparkles.forEach(s => {
                        if (s.clip_id === clip.id) {
                            s.start_frame = newStart;
                        }
                    });
                    
                    segment.style.left = `${newStart * state.pixelsPerFrame}px`;
                    segment.style.width = `${Math.max(20, (origEnd - newStart) * state.pixelsPerFrame)}px`;
                    const badge = segment.querySelector('.segment-badge');
                    if (badge) badge.textContent = `${count} błysk. (${newStart}-${origEnd})`;
                    
                    drawSparkles();
                };
                
                const onMouseUp = () => {
                    window.removeEventListener('mousemove', onMouseMove);
                    window.removeEventListener('mouseup', onMouseUp);
                    renderTimelineTracks();
                    drawSparkles();
                };
                
                window.addEventListener('mousemove', onMouseMove);
                window.addEventListener('mouseup', onMouseUp);
            });
        }
        
        if (rightHandle) {
            rightHandle.addEventListener('mousedown', (e) => {
                e.stopPropagation();
                let startX = e.clientX;
                const origStart = clip.start_frame;
                const origEnd = clip.end_frame;
                
                const onMouseMove = (moveEvt) => {
                    const diffX = moveEvt.clientX - startX;
                    const diffFrames = Math.round(diffX / state.pixelsPerFrame);
                    
                    let newEnd = Math.max(origStart + 1, Math.min(state.totalFrames, origEnd + diffFrames));
                    clip.end_frame = newEnd;
                    
                    state.sparkles.forEach(s => {
                        if (s.clip_id === clip.id) {
                            s.end_frame = newEnd;
                        }
                    });
                    
                    segment.style.width = `${Math.max(20, (newEnd - origStart) * state.pixelsPerFrame)}px`;
                    const badge = segment.querySelector('.segment-badge');
                    if (badge) badge.textContent = `${count} błysk. (${origStart}-${newEnd})`;
                    
                    drawSparkles();
                };
                
                const onMouseUp = () => {
                    window.removeEventListener('mousemove', onMouseMove);
                    window.removeEventListener('mouseup', onMouseUp);
                    renderTimelineTracks();
                    drawSparkles();
                };
                
                window.addEventListener('mousemove', onMouseMove);
                window.addEventListener('mouseup', onMouseUp);
            });
        }
        
        container.appendChild(segment);
    });
}

// BRUSH SIZE SELECTOR & ZOOM CONTROLS
function setupSizeSelector() {
    if (brushSizeInput) {
        const onSizeChange = () => {
            let val = parseFloat(brushSizeInput.value);
            if (isNaN(val) || val <= 0) {
                val = 0.01;
                brushSizeInput.value = '0.01';
            }
            state.selectedSizeMultiplier = val;
            // Zmiana rozmiaru pędzla dotyczy wyłącznie NOWO DODAWANYCH punktów!
            // Istniejące punkty zachowują swój pierwotnie nadany rozmiar.
        };

        brushSizeInput.addEventListener('input', onSizeChange);
        brushSizeInput.addEventListener('change', onSizeChange);
    }
    setupZoom();
}

function setupZoom() {
    const applyZoom = (newZoom) => {
        state.zoomLevel = Math.max(0.25, Math.min(4.0, Math.round(newZoom * 100) / 100));
        if (zoomLevelVal) zoomLevelVal.textContent = `${Math.round(state.zoomLevel * 100)}%`;
        if (mediaViewport) {
            mediaViewport.style.transform = `scale(${state.zoomLevel})`;
            mediaViewport.style.transformOrigin = 'center center';
        }
    };
    
    if (btnZoomIn) btnZoomIn.addEventListener('click', () => applyZoom(state.zoomLevel + 0.25));
    if (btnZoomOut) btnZoomOut.addEventListener('click', () => applyZoom(state.zoomLevel - 0.25));
    if (btnZoomReset) btnZoomReset.addEventListener('click', () => applyZoom(1.0));
    
    if (previewAreaContainer) {
        previewAreaContainer.addEventListener('wheel', (e) => {
            if (e.ctrlKey || e.metaKey) {
                e.preventDefault();
                const delta = e.deltaY < 0 ? 0.15 : -0.15;
                applyZoom(state.zoomLevel + delta);
            }
        }, { passive: false });
    }
}

// UPLOAD DRAG & DROP
function setupUpload() {
    uploadDropzone.addEventListener('click', () => {
        fileUploadInput.click();
    });

    uploadDropzone.addEventListener('dragover', (e) => {
        e.preventDefault();
        uploadDropzone.style.borderColor = 'var(--color-primary)';
    });

    uploadDropzone.addEventListener('dragleave', () => {
        uploadDropzone.style.borderColor = 'var(--border-color)';
    });

    uploadDropzone.addEventListener('drop', (e) => {
        e.preventDefault();
        uploadDropzone.style.borderColor = 'var(--border-color)';
        const files = e.dataTransfer.files;
        if (files.length > 0) {
            handleFileUpload(files[0]);
        }
    });

    fileUploadInput.addEventListener('change', () => {
        if (fileUploadInput.files.length > 0) {
            handleFileUpload(fileUploadInput.files[0]);
        }
    });
}

// AUTO RASTERIZE SVG ON CLIENT SIDE & UPLOAD PNG
function handleFileUpload(file) {
    loadLocalFile(file);
}

async function uploadFileToServer(file) {
    const formData = new FormData();
    formData.append('file', file);

    try {
        const res = await fetch(API_BASE + '/api/upload', {
            method: 'POST',
            body: formData
        });
        const data = await res.json();
        
        if (data.error) {
            logMessage(`Błąd przesyłania: ${data.error}`, 'error');
            return;
        }

        logMessage(`✓ Plik zapisany pomyślnie: ${data.filename}`, 'success');
        await loadWorkspaceFiles(); // Odśwież listy
        
        // Jeśli to plik tła, załaduj podgląd
        const ext = data.filename.split('.').pop().toLowerCase();
        if (['jpg', 'jpeg', 'png', 'mp4'].includes(ext)) {
            // Zaznacz nowy plik na liście
            setTimeout(() => {
                if (sourceFilesSelect) for (let opt of sourceFilesSelect.options) {
                    if (opt.value === data.filename) {
                        opt.selected = true;
                        if (sourceFilesSelect) sourceFilesSelect.dispatchEvent(new Event('change'));
                        break;
                    }
                }
            }, 100);
        }
    } catch (err) {
        logMessage(`Błąd przesyłania: ${err.message}`, 'error');
    }
}

// LOGS
function logMessage(msg, type = 'info') {
    const line = document.createElement('div');
    line.className = `log-line ${type}`;
    line.textContent = `[${new Date().toLocaleTimeString()}] ${msg}`;
    consoleLogs.appendChild(line);
    consoleLogs.scrollTop = consoleLogs.scrollHeight;
}

// PRESET MANAGEMENT
async function loadPresetsList() { console.log("GitHub Pages mode: no presets."); }

function getSettingsObject() {
    const selectedSources = sourceFilesSelect ? Array.from(sourceFilesSelect.selectedOptions).map(o => o.value) : [];
    
    return {
        // general
        source_paths: selectedSources,
        snowflake_texture_path: snowflakeTextureSelect.value,
        sparkle_texture_path: sparkleTextureSelect.value,
        output_video_path: outputNameInput.value,
        video_duration: parseInt(videoDurationInput.value),
        fps: parseInt(videoFpsInput.value),
        
        // snow
        num_snowflakes: parseInt((typeof snowDensityInput !== 'undefined' && snowDensityInput) ? snowDensityInput.value : snowDensitySlider.value),
        snowflake_min_size: parseInt(snowMinSizeInput.value),
        snowflake_max_size: parseInt(snowMaxSizeInput.value),
        snowflake_opacity: parseInt(snowOpacitySlider.value),
        depth_layers: parseInt(snowDepthLayersInput.value),
        depth_strength: parseFloat(snowDepthStrengthSlider.value),
        parallax_speed: parseFloat(snowParallaxSlider.value),
        fall_speed_mode: snowFallModeSelect.value,
        fall_speed: parseFloat(snowFallSpeedInput.value),
        fall_speed_min: parseFloat(snowFallMinInput.value),
        fall_speed_max: parseFloat(snowFallMaxInput.value),
        wind_x: parseFloat(snowWindXInput.value),
        wind_y: parseFloat(snowWindYInput.value),
        wind_z: parseFloat(snowWindZInput.value),
        wind_strength: parseFloat(snowWindStrengthInput.value),
        wind_gust_frequency: parseFloat(snowWindGustInput.value),
        turbulence: parseFloat(snowTurbulenceInput.value),
        randomness_movement: parseFloat(snowRandomnessInput.value),
        enable_fade_out: snowEnableFadeCheckbox.checked,
        fade_start_percent: parseInt(snowFadeStartInput.value),
        fade_end_percent: parseInt(snowFadeEndInput.value),
        blur_radius: parseInt(snowBlurInput.value),
        glow_strength: parseFloat(snowGlowInput.value),
        blend_mode: snowBlendModeSelect.value,
        depth_of_field_focus: parseFloat(snowDofFocusSlider.value),
        depth_of_field_blur: parseFloat(snowDofBlurSlider.value),
        dof_haze_strength: parseFloat(snowDofHazeSlider.value),
        dof_lens_fade: parseFloat(snowDofLensFadeSlider.value),

        // sparkles
        fade_in_frames: parseInt(sparkleFadeInInput.value),
        hold_frames: parseInt(sparkleHoldInput.value),
        fade_out_frames: parseInt(sparkleFadeOutInput.value),
        gap_min_frames: parseInt(sparkleGapMinInput.value),
        gap_max_frames: parseInt(sparkleGapMaxInput.value),
        appearance_frequency: parseFloat(sparkleFrequencySlider.value),
        jitter_amount: parseFloat(sparkleJitterSlider.value),
        animation_stability: sparkleStabilitySelect.value,
        enable_smooth_animation: sparkleSmoothAnimCheckbox.checked,
        size_min: parseInt(sparkleSizeMinInput.value),
        size_max: parseInt(sparkleSizeMaxInput.value),
        sparkle_opacity: (sparkleOpacityInput ? parseFloat(sparkleOpacityInput.value) : ((parseInt(sparkleOpacitySlider.value) || 255) / 255.0)),
        use_gaussian_blur: sparkleUseBlurCheckbox.checked,
        size_smoothing: sparkleSizeSmoothCheckbox.checked,
        sparkle_blend_mode: sparkleBlendModeSelect.value,
        enable_sparkle_blinking: sparkleEnableBlinkingCheckbox.checked,
        sparkle_blinking_speed: parseFloat(sparkleBlinkingSpeedSlider.value),
        
        // sparkles coords
        sparkles: state.sparkles
    };
}

function applySettingsObject(settings) {
    if (!settings) return;
    
    // Select sources
    if (settings.source_paths && settings.source_paths.length > 0) {
        if (sourceFilesSelect) for (let opt of sourceFilesSelect.options) {
            opt.selected = settings.source_paths.includes(opt.value);
        }
        if (sourceFilesSelect) sourceFilesSelect.dispatchEvent(new Event('change'));
    }

    if (settings.snowflake_texture_path) snowflakeTextureSelect.value = settings.snowflake_texture_path;
    if (settings.sparkle_texture_path) sparkleTextureSelect.value = settings.sparkle_texture_path;
    if (settings.output_video_path) outputNameInput.value = settings.output_video_path;
    if (settings.video_duration) videoDurationInput.value = settings.video_duration;
    if (settings.fps) videoFpsInput.value = settings.fps;
    
    // snow
    if (settings.num_snowflakes) {
        snowDensitySlider.value = settings.num_snowflakes;
        snowDensityVal.textContent = settings.num_snowflakes;
        if (typeof snowDensityInput !== 'undefined' && snowDensityInput) snowDensityInput.value = settings.num_snowflakes;
    }
    if (settings.snowflake_min_size) snowMinSizeInput.value = settings.snowflake_min_size;
    if (settings.snowflake_max_size) snowMaxSizeInput.value = settings.snowflake_max_size;
    if (settings.snowflake_opacity) {
        snowOpacitySlider.value = settings.snowflake_opacity;
        snowOpacityVal.textContent = settings.snowflake_opacity;
    }
    if (settings.depth_layers) snowDepthLayersInput.value = settings.depth_layers;
    if (settings.depth_strength) {
        snowDepthStrengthSlider.value = settings.depth_strength;
        snowDepthStrengthVal.textContent = settings.depth_strength;
    }
    if (settings.parallax_speed) {
        snowParallaxSlider.value = settings.parallax_speed;
        snowParallaxVal.textContent = settings.parallax_speed;
    }
    if (settings.fall_speed_mode) {
        snowFallModeSelect.value = settings.fall_speed_mode;
        snowFallModeSelect.dispatchEvent(new Event('change'));
    }
    if (settings.fall_speed) snowFallSpeedInput.value = settings.fall_speed;
    if (settings.fall_speed_min) snowFallMinInput.value = settings.fall_speed_min;
    if (settings.fall_speed_max) snowFallMaxInput.value = settings.fall_speed_max;
    if (settings.wind_x) snowWindXInput.value = settings.wind_x;
    if (settings.wind_y) snowWindYInput.value = settings.wind_y;
    if (settings.wind_z) snowWindZInput.value = settings.wind_z;
    if (settings.wind_strength) snowWindStrengthInput.value = settings.wind_strength;
    if (settings.wind_gust_frequency) snowWindGustInput.value = settings.wind_gust_frequency;
    if (settings.turbulence) snowTurbulenceInput.value = settings.turbulence;
    if (settings.randomness_movement) snowRandomnessInput.value = settings.randomness_movement;
    
    if (settings.enable_fade_out !== undefined) {
        snowEnableFadeCheckbox.checked = settings.enable_fade_out;
        snowEnableFadeCheckbox.dispatchEvent(new Event('change'));
    }
    if (settings.fade_start_percent) snowFadeStartInput.value = settings.fade_start_percent;
    if (settings.fade_end_percent) snowFadeEndInput.value = settings.fade_end_percent;
    if (settings.blur_radius) snowBlurInput.value = settings.blur_radius;
    if (settings.glow_strength) snowGlowInput.value = settings.glow_strength;
    if (settings.blend_mode) snowBlendModeSelect.value = settings.blend_mode;
    
    if (settings.depth_of_field_focus !== undefined) {
        snowDofFocusSlider.value = settings.depth_of_field_focus;
        snowDofFocusVal.textContent = settings.depth_of_field_focus;
    }
    if (settings.depth_of_field_blur !== undefined) {
        snowDofBlurSlider.value = settings.depth_of_field_blur;
        snowDofBlurVal.textContent = settings.depth_of_field_blur;
    }
    if (settings.dof_haze_strength !== undefined) {
        snowDofHazeSlider.value = settings.dof_haze_strength;
        snowDofHazeVal.textContent = settings.dof_haze_strength;
    }
    if (settings.dof_lens_fade !== undefined) {
        snowDofLensFadeSlider.value = settings.dof_lens_fade;
        snowDofLensFadeVal.textContent = settings.dof_lens_fade;
    }

    // sparkles
    if (settings.fade_in_frames) sparkleFadeInInput.value = settings.fade_in_frames;
    if (settings.hold_frames) sparkleHoldInput.value = settings.hold_frames;
    if (settings.fade_out_frames) sparkleFadeOutInput.value = settings.fade_out_frames;
    if (settings.gap_min_frames) sparkleGapMinInput.value = settings.gap_min_frames;
    if (settings.gap_max_frames) sparkleGapMaxInput.value = settings.gap_max_frames;
    
    if (settings.appearance_frequency) {
        sparkleFrequencySlider.value = settings.appearance_frequency;
        sparkleFrequencyVal.textContent = settings.appearance_frequency;
    }
    if (settings.jitter_amount) {
        sparkleJitterSlider.value = settings.jitter_amount;
        sparkleJitterVal.textContent = settings.jitter_amount;
    }
    if (settings.animation_stability) sparkleStabilitySelect.value = settings.animation_stability;
    if (settings.enable_smooth_animation !== undefined) sparkleSmoothAnimCheckbox.checked = settings.enable_smooth_animation;
    if (settings.size_min) sparkleSizeMinInput.value = settings.size_min;
    if (settings.size_max) sparkleSizeMaxInput.value = settings.size_max;
    if (settings.sparkle_opacity !== undefined) {
        let opVal = parseFloat(settings.sparkle_opacity);
        if (opVal > 1.0) opVal = opVal / 255.0;
        opVal = Math.max(0.0, Math.min(1.0, opVal));
        if (sparkleOpacitySlider) sparkleOpacitySlider.value = Math.round(opVal * 255);
        if (sparkleOpacityInput) sparkleOpacityInput.value = opVal.toFixed(2);
        if (sparkleOpacityVal) sparkleOpacityVal.textContent = `${Math.round(opVal * 100)}%`;
    }
    if (settings.use_gaussian_blur !== undefined) sparkleUseBlurCheckbox.checked = settings.use_gaussian_blur;
    if (settings.size_smoothing !== undefined) sparkleSizeSmoothCheckbox.checked = settings.size_smoothing;
    if (settings.sparkle_blend_mode) sparkleBlendModeSelect.value = settings.sparkle_blend_mode;
    
    if (settings.enable_sparkle_blinking !== undefined) {
        sparkleEnableBlinkingCheckbox.checked = settings.enable_sparkle_blinking;
        sparkleEnableBlinkingCheckbox.dispatchEvent(new Event('change'));
    }
    if (settings.sparkle_blinking_speed !== undefined) {
        sparkleBlinkingSpeedSlider.value = settings.sparkle_blinking_speed;
        sparkleBlinkingSpeedVal.textContent = settings.sparkle_blinking_speed;
    }
    
    // Sparkles coordinates
    if (settings.sparkles) {
        state.sparkles = settings.sparkles;
        updateSparklesDisplay();
        drawSparkles();
        renderTimelineTracks();
    }
}

function setupPresetControls() {
    if (btnLoadPreset) btnLoadPreset.addEventListener('click', async () => {
        const name = presetSelect.value;
        if (!name) return;
        
        try {
            const res = await fetch(API_BASE + `/api/presets/${encodeURIComponent(name)}`);
            const settings = await res.json();
            applySettingsObject(settings);
            logMessage(`Wczytano preset: ${name}`, 'success');
        } catch (err) {
            logMessage(`Błąd wczytywania presetu: ${err.message}`, 'error');
        }
    });

    if (btnSavePreset) btnSavePreset.addEventListener('click', async () => {
        let name = prompt("Podaj nazwę presetu (bez rozszerzenia):");
        if (!name) return;
        name = name.trim();
        if (!name.endsWith('.json')) name += '.json';

        const settings = getSettingsObject();

        try {
            const res = await fetch(API_BASE + '/api/presets', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ name, settings })
            });
            const data = await res.json();
            if (data.error) {
                logMessage(`Błąd zapisu: ${data.error}`, 'error');
            } else {
                logMessage(`✓ Zapisano preset: ${name}`, 'success');
                await loadPresetsList();
                presetSelect.value = name;
            }
        } catch (err) {
            logMessage(`Błąd zapisu: ${err.message}`, 'error');
        }
    });
}

// GENERATION DRIVERS AND SSE LOGGER
function setupActionButtons() {
    document.querySelectorAll('#btn-generate-sparkles, .btn-generate-sparkles').forEach(btn => {
        btn.addEventListener('click', () => generateClientSide('sparkles'));
    });
    document.querySelectorAll('#btn-generate-snow, .btn-generate-snow').forEach(btn => {
        btn.addEventListener('click', () => generateClientSide('snow'));
    });
    document.querySelectorAll('#btn-generate-both, #btn-generate-both-snow, #btn-generate-both-sparkles, .btn-generate-both').forEach(btn => {
        btn.addEventListener('click', () => generateClientSide('pipeline'));
    });
}

async function runGeneration(endpoint) {
    if (state.activeGeneration) {
        logMessage("Generowanie już trwa!", "warning");
        return;
    }

    if (state.offlineMode) {
        generateClientSide(endpoint);
        return;
    }

    // Walidacje
    const settings = getSettingsObject();
    if (settings.source_paths.length === 0) {
        alert("Musisz zaznaczyć przynajmniej jeden plik źródłowy w zakładce Pliki!");
        return;
    }
    if (endpoint === 'sparkles' && state.sparkles.length === 0) {
        if (!confirm("Nie postawiłeś żadnych punktów błysków! Wygenerować wideo bez błysków?")) return;
    }

    state.activeGeneration = true;
    updateStatusTag('running', 'Przetwarzanie...');
    progressBar.style.width = '0%';
    progressText.textContent = '0%';
    
    // Clear logs and print start
    consoleLogs.innerHTML = '';
    logMessage(`Rozpoczynam renderowanie: ${endpoint.toUpperCase()}...`, 'info');

    // Start SSE listener
    setupLogStream();

    try {
        const res = await fetch(API_BASE + `/api/generate/${endpoint}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(settings)
        });
        const data = await res.json();
        
        if (data.error) {
            logMessage(`Błąd uruchamiania generowania: ${data.error}`, 'error');
            stopGeneration(false);
        }
    } catch (err) {
        logMessage(`Błąd sieci: ${err.message}`, 'error');
        stopGeneration(false);
    }
}

function setupLogStream() {
    if (state.eventSource) {
        state.eventSource.close();
    }

    state.eventSource = new EventSource(API_BASE + '/api/logs');
    
    state.eventSource.onmessage = (event) => {
        try {
            const data = JSON.parse(event.data);
            
            if (data.type === 'log') {
                let colorClass = 'info';
                if (data.message.includes('✅') || data.message.includes('✓')) colorClass = 'success';
                if (data.message.includes('⚠️')) colorClass = 'warning';
                if (data.message.includes('❌') || data.message.includes('Błąd')) colorClass = 'error';
                
                logMessage(data.message, colorClass);
            } 
            else if (data.type === 'progress') {
                const pct = Math.round(data.value);
                progressBar.style.width = `${pct}%`;
                progressText.textContent = `${pct}%`;
            }
            else if (data.type === 'complete') {
                logMessage(`✓ Renderowanie zakończone pomyślnie! Wyjściowy plik zapisany jako: ${data.output}`, 'success');
                stopGeneration(true);
                // Refresh list of files
                loadWorkspaceFiles();
            }
            else if (data.type === 'failed') {
                logMessage(`❌ Renderowanie nie powiodło się!`, 'error');
                stopGeneration(false);
            }
        } catch (err) {
            console.error("SSE parse error:", err);
        }
    };

    state.eventSource.onerror = (err) => {
        console.error("SSE connection error:", err);
        state.eventSource.close();
    };
}

function stopGeneration(success) {
    state.activeGeneration = false;
    if (typeof previewVideo !== 'undefined' && previewVideo) {
        try { previewVideo.pause(); } catch(e) {}
    }
    if (state.eventSource) {
        state.eventSource.close();
        state.eventSource = null;
    }
    updateStatusTag(success ? 'success' : 'error', success ? 'Zakończono' : 'Błąd');
}

function updateStatusTag(type, label) {
    statusTag.className = `status-indicator ${type}`;
    statusTag.textContent = label;
}

// ============ OFFLINE / CLIENT-SIDE RENDERING AND SIMULATION ============

async function checkServerConnection() { state.mode = "local"; console.log("GitHub Pages mode: always local."); }

function loadLocalFile(file) {
    logMessage(`Wczytuję plik lokalny: ${file.name}...`, 'info');
    state.sourceWidth = 0;
    state.sourceHeight = 0;
    state.isVideo = file.type.startsWith('video/') || /\.(mp4|webm|mov|mkv|avi)$/i.test(file.name);
    state.localFile = file;
    
    noMediaPlaceholder.style.display = 'none';
    mediaViewport.style.display = 'flex';
    
    if (state.isVideo) {
        // Ensure the Blob has an explicit video MIME type so Chromium doesn't fail demuxing on Windows
        let videoBlob = file;
        if (!file.type || file.type === 'application/octet-stream') {
            const ext = file.name.split('.').pop().toLowerCase();
            const mime = ext === 'webm' ? 'video/webm' : 'video/mp4';
            videoBlob = file.slice(0, file.size, mime);
        }
        const fileURL = URL.createObjectURL(videoBlob);
        previewImage.style.display = 'none';
        previewVideo.style.display = 'block';
        previewVideo.muted = true;
        previewVideo.playsInline = true;
        previewVideo.onerror = (e) => {
            const errCode = previewVideo.error ? previewVideo.error.code : 'nieznany';
            const errMsg = previewVideo.error ? previewVideo.error.message : '';
            logMessage(`❌ Błąd odtwarzania wideo (kod ${errCode}): Przeglądarka nie może zdekodować tego strumienia wideo. Upewnij się, że plik MP4 używa standardowego kodeka H.264 (AVC) lub VP8/VP9/WebM. ${errMsg}`, 'error');
        };
        previewVideo.src = fileURL;
        previewVideo.load();
        previewVideo.onloadedmetadata = () => {
            state.sourceWidth = previewVideo.videoWidth;
            state.sourceHeight = previewVideo.videoHeight;
            let dur = Math.round(previewVideo.duration);
            if (!isFinite(dur) || isNaN(dur) || dur <= 0) {
                dur = parseInt(videoDurationInput.value) || 8;
            } else {
                if (videoDurationInput) videoDurationInput.value = dur;
            }
            state.fps = parseInt(videoFpsInput.value) || 30;
            state.totalFrames = Math.max(1, dur * state.fps);
            previewAreaContainer.style.height = "auto";
            resizeOverlay(previewVideo);
            if (videoTimelineEditor) videoTimelineEditor.style.display = 'flex';
            initTimelineRuler();
            renderTimelineTracks();
            logMessage(`✓ Załadowano wideo: ${state.sourceWidth}x${state.sourceHeight} (${dur}s, ${state.totalFrames} klatek)`, 'success');
        };
    } else {
        const reader = new FileReader();
        reader.onload = (e) => {
            const dataUrl = e.target.result;
            previewVideo.style.display = 'none';
            previewImage.style.display = 'block';
            previewImage.src = dataUrl;
            previewImage.onload = () => {
                state.sourceWidth = previewImage.naturalWidth;
                state.sourceHeight = previewImage.naturalHeight;
                state.fps = parseInt(videoFpsInput.value) || 30;
                const dur = parseInt(videoDurationInput.value) || 8;
                state.totalFrames = Math.max(1, dur * state.fps);
                state.currentFrame = 0;
                previewAreaContainer.style.height = "auto";
                resizeOverlay(previewImage);
                if (videoTimelineEditor) videoTimelineEditor.style.display = 'flex';
                initTimelineRuler();
                renderTimelineTracks();
                updatePlayhead();
                logMessage(`✓ Załadowano obraz: ${state.sourceWidth}x${state.sourceHeight}`, 'success');
            };
        };
        reader.readAsDataURL(file);
    }
}

class SnowParticle {
    constructor(w, h, minSize, maxSize, depthLayers, fallMode, fallSpeed, fallMin, fallMax) {
        this.w = w;
        this.h = h;
        this.size = Math.random() * (maxSize - minSize) + minSize;
        this.depth = Math.floor(Math.random() * depthLayers);
        this.depthFactor = this.depth / Math.max(1, depthLayers - 1);
        
        if (fallMode === 'uniform') {
            this.vy = fallSpeed;
        } else {
            this.vy = Math.random() * (fallMax - fallMin) + fallMin;
        }
        
        this.x = Math.random() * (w + 200) - 100;
        this.y = Math.random() * (h + 100) - 50;
        this.vx = Math.random() * 2 - 1;
        this.wobble = Math.random() * Math.PI * 2;
        this.wobbleSpeed = Math.random() * 0.1 + 0.05;
    }
    
    update(windX, windInfluence, turbulence, randomness, amount, parallaxSpeed) {
        this.vx += windX * windInfluence * 0.01;
        
        const parallaxMult = 0.3 + this.depthFactor * (1.0 + parallaxSpeed * 0.5);
        this.vx += (Math.random() * 2 - 1) * turbulence * 0.05;
        this.vx += (Math.random() * 2 - 1) * randomness * amount * 0.01;
        
        this.wobble += this.wobbleSpeed;
        this.vx += Math.sin(this.wobble) * 0.02;
        
        this.x += this.vx * parallaxMult;
        this.y += this.vy * parallaxMult;
        
        if (this.x > this.w + 100) this.x = -100;
        else if (this.x < -100) this.x = this.w + 100;
        
        if (this.y > this.h + 50) {
            this.y = -50;
            this.x = Math.random() * (this.w + 200) - 100;
        }
    }
}

function drawSnowflake(ctx, x, y, radius, opacity, depthFactor, glowStrength, dofFocus = 0.5, dofBlurStrength = 1.0, dofHaze = 0.3, dofLensFade = 0.5, img = null) {
    const sizeWithDepth = radius * (0.3 + depthFactor * 0.7);
    if (sizeWithDepth <= 0) return;
    
    // Atmospheric haze and lens fade factors
    const hazeMult = 1.0 - (1.0 - depthFactor) * (dofHaze || 0.3);
    let lensMult = 1.0;
    if (depthFactor > 0.8) {
        lensMult = 1.0 - ((depthFactor - 0.8) / 0.2) * (dofLensFade || 0.5);
    }
    
    const alpha = (opacity / 255.0) * (0.5 + depthFactor * 0.5) * hazeMult * lensMult;
    const finalAlpha = Math.max(0.0, Math.min(1.0, alpha * (1.0 + (glowStrength || 0.5) * depthFactor)));
    if (finalAlpha <= 0.005) return;

    if (img && img.complete && img.naturalWidth > 0) {
        ctx.globalAlpha = finalAlpha;
        const dSize = sizeWithDepth * 2;
        ctx.drawImage(img, x - sizeWithDepth, y - sizeWithDepth, dSize, dSize);
    } else {
        const dSize = sizeWithDepth * 2;
        const grad = ctx.createRadialGradient(x, y, 0, x, y, dSize);
        grad.addColorStop(0, `rgba(255, 255, 255, ${finalAlpha})`);
        grad.addColorStop(0.35, `rgba(255, 255, 255, ${finalAlpha * 0.65})`);
        grad.addColorStop(1, 'rgba(255, 255, 255, 0)');
        
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(x, y, dSize, 0, Math.PI * 2);
        ctx.fill();
    }
}

// Precyzyjny dobór kodeka zgodnie ze specyfikacją W3C MediaRecorder API
function getPreferredMimeType(reqFormat) {
    const mp4Types = [
        'video/mp4;codecs=avc1.42E01E',
        'video/mp4;codecs=avc1',
        'video/mp4;codecs=h264',
        'video/mp4'
    ];
    const webmTypes = [
        'video/webm;codecs=vp9',
        'video/webm;codecs=vp8',
        'video/webm'
    ];

    if (reqFormat === 'mp4') {
        for (const t of mp4Types) {
            try {
                if (MediaRecorder.isTypeSupported(t)) return t;
            } catch(e) {}
        }
        for (const t of webmTypes) {
            try {
                if (MediaRecorder.isTypeSupported(t)) return t;
            } catch(e) {}
        }
    } else if (reqFormat === 'webm') {
        for (const t of webmTypes) {
            try {
                if (MediaRecorder.isTypeSupported(t)) return t;
            } catch(e) {}
        }
        for (const t of mp4Types) {
            try {
                if (MediaRecorder.isTypeSupported(t)) return t;
            } catch(e) {}
        }
    } else {
        // 'auto' - prefer standard H.264 avc1 MP4 first for universal smooth hardware playback
        const autoTypes = [
            'video/mp4;codecs=avc1.42E01E',
            'video/mp4;codecs=avc1',
            'video/mp4;codecs=h264',
            'video/mp4',
            'video/webm;codecs=vp9',
            'video/webm;codecs=vp8',
            'video/webm'
        ];
        for (const t of autoTypes) {
            try {
                if (MediaRecorder.isTypeSupported(t)) return t;
            } catch(e) {}
        }
    }
    return 'video/webm';
}

async function generateClientSide(type) {
    if (state.activeGeneration) return;
    
    if (!state.sourceWidth || !state.sourceHeight) {
        alert("Najpierw załaduj plik źródłowy!");
        return;
    }
    
    state.activeGeneration = true;
    updateStatusTag('running', 'Generowanie lokalne...');
    progressBar.style.width = '0%';
    progressText.textContent = '0%';
    consoleLogs.innerHTML = '';
    logMessage("Rozpoczynam renderowanie lokalne w przeglądarce...", "info");
    
    const duration = parseInt(videoDurationInput.value) || (state.isVideo && isFinite(previewVideo.duration) && previewVideo.duration > 0 ? Math.round(previewVideo.duration) : 8);
    const fps = parseInt(videoFpsInput.value) || state.fps || 30;
    const totalFrames = Math.max(1, duration * fps);
    const frameDuration = 1000 / fps;

    // Oblicz docelową rozdzielczość i parametry dopasowania
    const resKey = (typeof exportResolutionSelect !== 'undefined' && exportResolutionSelect) ? exportResolutionSelect.value : 'original';
    const targetDims = getResolutionDimensions(resKey, state.sourceWidth, state.sourceHeight);
    const drawParams = calculateFrameDrawParams(targetDims.width, targetDims.height, state.sourceWidth, state.sourceHeight);
    
    const renderCanvas = document.createElement('canvas');
    renderCanvas.width = drawParams.targetW;
    renderCanvas.height = drawParams.targetH;
    renderCanvas.style.position = 'fixed';
    renderCanvas.style.left = '-99999px';
    renderCanvas.style.top = '0';
    renderCanvas.style.width = `${drawParams.targetW}px`;
    renderCanvas.style.height = `${drawParams.targetH}px`;
    renderCanvas.style.opacity = '1';
    renderCanvas.style.visibility = 'visible';
    renderCanvas.style.pointerEvents = 'none';
    document.body.appendChild(renderCanvas);
    const ctx = renderCanvas.getContext('2d');
    
    const cleanupCanvas = () => {
        if (renderCanvas && renderCanvas.parentNode) {
            renderCanvas.parentNode.removeChild(renderCanvas);
        }
    };
    
    // Ustal format i sprawdzony kodek w przeglądarce
    const reqFormat = (typeof exportFormatSelect !== 'undefined' && exportFormatSelect) ? exportFormatSelect.value : 'auto';
    const mimeType = getPreferredMimeType(reqFormat);
    
    const isMp4 = mimeType.startsWith('video/mp4');
    const extension = isMp4 ? '.mp4' : '.webm';
    
    if (reqFormat === 'mp4' && !isMp4) {
        logMessage("ℹ️ Twoja przeglądarka nie obsługuje zapisu bezpośredniego do MP4 (H.264). Eksportuję w formacie WebM.", "warning");
    }
    
    let rawFilename = outputNameInput.value.trim() || (type === 'snow' ? 'sniezki' : 'Blask_ze_sniegiem');
    rawFilename = rawFilename.replace(/\.(mp4|webm|avi|mov)$/i, '');
    const targetFilename = `${rawFilename}${extension}`;

    logMessage(`Rozdzielczość: ${drawParams.targetW}x${drawParams.targetH} (${drawParams.mode === 'letterbox' ? 'Czarne paski w tle' : (drawParams.mode === 'crop' ? 'Przycięcie krawędzi' : '1:1')})`, 'info');
    logMessage(`Format wideo: ${mimeType} (${isMp4 ? 'MP4' : 'WebM'})`, 'info');
    
    let recorder;
    let chunks = [];
    const stream = renderCanvas.captureStream(fps);
    const streamTrack = stream.getVideoTracks()[0];
    
    const bitrates = { '210x240': 1500000, 'hd': 5000000, 'fullhd': 8500000 };
    const targetBitrate = bitrates[resKey] || 6000000;

    try {
        recorder = new MediaRecorder(stream, { mimeType, videoBitsPerSecond: targetBitrate });
        recorder.ondataavailable = e => {
            if (e.data && e.data.size > 0) chunks.push(e.data);
        };
        recorder.onerror = e => {
            const errDetail = e.error ? (e.error.name + ': ' + e.error.message) : (e.message || 'Nieznany błąd enkodera');
            logMessage(`❌ Błąd MediaRecorder: ${errDetail}`, 'error');
            stopGeneration(false);
        };
        recorder.onstop = async () => {
            cleanupCanvas();
            logMessage("Finalizowanie i sprawdzanie pliku wideo...", "info");
            if (!chunks || chunks.length === 0) {
                logMessage("❌ Błąd MediaRecorder: Przeglądarka nie zapisała klatek. W opcjach zapisu wybierz format WebM (VP8/VP9) lub rozdzielczość HD (1280x720).", "error");
                stopGeneration(false);
                return;
            }
            let rawBlob = new Blob(chunks, { type: mimeType });
            if (rawBlob.size === 0) {
                logMessage("❌ Błąd: Wygenerowany plik wideo ma 0 bajtów. Wybierz rozdzielczość HD (1280x720) lub format WebM.", "error");
                stopGeneration(false);
                return;
            }
            let finalBlob = rawBlob;
            if (mimeType.includes('webm') && finalBlob.size > 40) {
                finalBlob = await fixWebmDuration(rawBlob, duration * 1000);
            }
            const url = URL.createObjectURL(finalBlob);
            const a = document.createElement('a');
            a.href = url;
            a.download = targetFilename;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            logMessage(`✓ Zapisano plik wideo jako ${a.download} (${(finalBlob.size / 1024 / 1024).toFixed(2)} MB)`, "success");
            stopGeneration(true);
        };
    } catch (e) {
        logMessage(`❌ Błąd inicjalizacji nagrywania: ${e.message}`, "error");
        stopGeneration(false);
        return;
    }
    
    // Inicjalizacja płatków śniegu
    const snowParticles = [];
    if (type === 'snow' || type === 'pipeline') {
        const density = (typeof snowDensityInput !== 'undefined' && snowDensityInput ? parseInt(snowDensityInput.value) : 0) || (snowDensitySlider ? parseInt(snowDensitySlider.value) : 450) || 450;
        const minSize = parseInt(snowMinSizeInput.value) || 3;
        const maxSize = parseInt(snowMaxSizeInput.value) || 12;
        const depthLayers = parseInt(snowDepthLayersInput.value) || 12;
        const fallMode = snowFallModeSelect.value;
        const fallSpeed = parseFloat(snowFallSpeedInput.value) || 1.5;
        const fallMin = parseFloat(snowFallMinInput.value) || 0.5;
        const fallMax = parseFloat(snowFallMaxInput.value) || 3.0;
        
        for (let i = 0; i < density; i++) {
            snowParticles.push(new SnowParticle(drawParams.targetW, drawParams.targetH, minSize, maxSize, depthLayers, fallMode, fallSpeed, fallMin, fallMax));
        }
    }
    
    // Inicjalizacja błysków
    let sparklesList = [];
    if (type === 'sparkles' || type === 'pipeline') {
        sparklesList = state.sparkles.map(s => {
            const spkType = s.sparkle_type || state.selectedSparkleType || '1';
            const isAnim = spkType !== '1' && SPARKLE_PRESETS[spkType] && SPARKLE_PRESETS[spkType].isAnimated;
            const sEnd = (s.end_frame !== undefined && s.end_frame > 0) ? s.end_frame : totalFrames;
            const sStart = (s.start_frame !== undefined && s.start_frame < sEnd) ? s.start_frame : 0;
            return {
                x: s.x,
                y: s.y,
                size_category: s.size_category,
                size_multiplier: s.size_multiplier,
                layer: s.layer || 'sparkles',
                sparkle_type: spkType,
                is_animated: isAnim,
                start_frame: sStart,
                end_frame: sEnd,
                timing_mode: s.timing_mode || 'manual',
                frame_offset: s.frame_offset !== undefined ? s.frame_offset : Math.floor(Math.random() * 50),
                gap_duration: Math.floor(Math.random() * (parseInt(sparkleGapMaxInput.value) - parseInt(sparkleGapMinInput.value))) + parseInt(sparkleGapMinInput.value),
                should_appear: isAnim ? true : (Math.random() < parseFloat(sparkleFrequencySlider.value)),
                prev_size: 0
            };
        });
    }
    
    let sparkleImg = new Image();
    const sparkleVal = getCurrentSparkleTextureSrc();
    sparkleImg.src = sparkleVal;
    if (!sparkleImg.complete) {
        await new Promise(resolve => {
            sparkleImg.onload = resolve;
            sparkleImg.onerror = resolve;
        });
    }

    let snowImg = new Image();
    const snowVal = (typeof snowflakeTextureSelect !== 'undefined' && snowflakeTextureSelect) ? snowflakeTextureSelect.value : null;
    snowImg.src = (snowVal && (snowVal.startsWith('blob:') || snowVal.startsWith('data:'))) 
        ? snowVal 
        : (snowVal && snowVal.includes('assets/') 
            ? (window.location.protocol === 'file:' ? BUILTIN_SNOW_TEXTURE : snowVal) 
            : BUILTIN_SNOW_TEXTURE);
    if (!snowImg.complete) {
        await new Promise(resolve => {
            snowImg.onload = resolve;
            snowImg.onerror = resolve;
        });
    }

    // Preload & process all needed animated sparkle spritesheets before recording starts
    if (type === 'sparkles' || type === 'pipeline') {
        const neededPresets = new Set(sparklesList.filter(s => s.is_animated).map(s => s.sparkle_type));
        for (const pid of neededPresets) {
            const preset = SPARKLE_PRESETS[pid];
            if (preset && preset.spritesheet) {
                if (!cachedSpriteImages[pid] || !cachedSpriteImages[pid].complete) {
                    const pImg = new Image();
                    pImg.src = preset.spritesheet;
                    await new Promise(r => {
                        pImg.onload = () => { cachedSpriteImages[pid] = pImg; r(); };
                        pImg.onerror = r;
                    });
                }
                if (!cachedKeyedCanvases[pid] || cachedKeyedCanvases[pid].length === 0) {
                    processKeyedFrames(pid);
                }
            }
        }
    }

    // Podwójny bufor roboczy eliminujący miganie klatek
    const backBufferCanvas = document.createElement('canvas');
    backBufferCanvas.width = drawParams.targetW;
    backBufferCanvas.height = drawParams.targetH;
    const bCtx = backBufferCanvas.getContext('2d', { willReadFrequently: true });

    // Funkcja kompozytowa rysująca kompletną klatkę (tło wideo/obraz + śnieg + błyski)
    const renderCompositeFrame = (curFrame) => {
        // 1. Tło
        bCtx.fillStyle = '#000000';
        bCtx.fillRect(0, 0, drawParams.targetW, drawParams.targetH);
        
        if (state.isVideo && previewVideo) {
            if (previewVideo.readyState >= 2 && previewVideo.videoWidth > 0) {
                bCtx.drawImage(previewVideo, drawParams.dstX, drawParams.dstY, drawParams.dstW, drawParams.dstH);
            }
        } else {
            bCtx.drawImage(previewImage, drawParams.dstX, drawParams.dstY, drawParams.dstW, drawParams.dstH);
        }

        // 2. Śnieg
        if (type === 'snow' || type === 'pipeline') {
            const windX = parseFloat(snowWindXInput.value) || 2.0;
            const windInfluence = (typeof snowWindStrengthInput !== 'undefined' && snowWindStrengthInput) ? ((parseFloat(snowWindStrengthInput.value) || 15.0) / 15.0) : 1.0;
            const turbulence = parseFloat(snowTurbulenceInput.value) || 0.5;
            const randomness = parseFloat(snowRandomnessInput.value) || 0.6;
            const amount = 2.5;
            const parallaxSpeed = parseFloat(snowParallaxSlider.value) || 1.0;
            const opacity = parseInt(snowOpacitySlider.value) || 220;
            const glowStrength = parseFloat(snowGlowInput.value) || 0.5;
            
            bCtx.save();
            const blendModes = {
                'normal': 'source-over',
                'addition': 'lighter',
                'screen': 'screen',
                'overlay': 'overlay',
                'multiply': 'multiply',
                'soft_light': 'soft-light',
                'hard_light': 'hard-light'
            };
            bCtx.globalCompositeOperation = blendModes[snowBlendModeSelect ? snowBlendModeSelect.value : 'normal'] || 'source-over';
            
            snowParticles.sort((a, b) => a.depth - b.depth);
            
            const dofFocus = parseFloat(snowDofFocusSlider.value);
            const dofBlur = parseFloat(snowDofBlurSlider.value);
            const dofHaze = parseFloat(snowDofHazeSlider.value);
            const dofLensFade = parseFloat(snowDofLensFadeSlider.value);
            
            snowParticles.forEach(p => {
                p.update(windX, windInfluence, turbulence, randomness, amount, parallaxSpeed);
                
                let alphaFactor = 1.0;
                if (snowEnableFadeCheckbox.checked) {
                    const startY = drawParams.targetH * (parseInt(snowFadeStartInput.value) / 100.0);
                    const endY = drawParams.targetH * (parseInt(snowFadeEndInput.value) / 100.0);
                    if (p.y > startY) {
                        if (p.y >= endY) alphaFactor = 0.0;
                        else alphaFactor = 1.0 - (p.y - startY) / (endY - startY);
                    }
                }
                
                drawSnowflake(bCtx, p.x, p.y, p.size, opacity * alphaFactor, p.depthFactor, glowStrength, dofFocus, dofBlur, dofHaze, dofLensFade, snowImg);
            });
            bCtx.restore();
        }

        // 3. Błyski
        if (type === 'sparkles' || type === 'pipeline') {
            bCtx.save();
            const canvasBlendModes = {
                'normal': 'source-over',
                'screen': 'screen',
                'addition': 'lighter',
                'lighter': 'lighter',
                'overlay': 'overlay',
                'multiply': 'multiply',
                'soft_light': 'soft-light',
                'hard_light': 'hard-light',
                'darken': 'darken',
                'color_dodge': 'color-dodge',
                'dodge': 'color-dodge'
            };
            const currentSparkleBlend = canvasBlendModes[sparkleBlendModeSelect ? sparkleBlendModeSelect.value : 'normal'] || 'source-over';
            bCtx.globalCompositeOperation = currentSparkleBlend;
            
            const fadeIn = parseInt(sparkleFadeInInput.value) || 10;
            const hold = parseInt(sparkleHoldInput.value) || 5;
            const fadeOut = parseInt(sparkleFadeOutInput.value) || 10;
            
            const enableBlinking = sparkleEnableBlinkingCheckbox.checked;
            const blinkingSpeed = parseFloat(sparkleBlinkingSpeedSlider.value);
            const jitterAmount = parseFloat(sparkleJitterSlider.value);
            
            const opacityMax = (typeof sparkleOpacityInput !== 'undefined' && sparkleOpacityInput && sparkleOpacityInput.value !== '')
                ? Math.max(0.0, Math.min(1.0, parseFloat(sparkleOpacityInput.value) || 0))
                : ((typeof sparkleOpacitySlider !== 'undefined' && sparkleOpacitySlider) ? ((parseInt(sparkleOpacitySlider.value) || 255) / 255.0) : 1.0);
            
            sparklesList.forEach(s => {
                const spkType = s.sparkle_type || state.selectedSparkleType || '1';
                const isAnim = s.is_animated;
                
                // Animowane presety
                if (isAnim) {
                    if (s.timing_mode === 'manual') {
                        if (curFrame < s.start_frame || curFrame > s.end_frame) return;
                    }
                    
                    const renderSparkleSize = getSparkleSize(s, drawParams.dstW);
                    const renderSparkleX = drawParams.dstX + (s.x / state.sourceWidth) * drawParams.dstW;
                    const renderSparkleY = drawParams.dstY + (s.y / state.sourceHeight) * drawParams.dstH;
                    const dx = renderSparkleX - renderSparkleSize / 2;
                    const dy = renderSparkleY - renderSparkleSize / 2;
                    const dw = renderSparkleSize;
                    const dh = renderSparkleSize;

                    const preset = SPARKLE_PRESETS[spkType];
                    const count = preset.frameCount || 41;
                    const speed = state.sparkleAnimSpeed !== undefined ? state.sparkleAnimSpeed : 1.0;
                    const rawFrame = (s.timing_mode === 'manual' ? Math.max(0, (curFrame - s.start_frame)) : (curFrame + s.frame_offset));
                    const animFrame = Math.floor(rawFrame * speed) % count;
                    const cols = preset.cols || 8;
                    const rows = Math.ceil(count / cols);
                    const col = animFrame % cols;
                    const row = Math.floor(animFrame / cols);

                    const frameCvs = getSparkleFrameCanvas(spkType, animFrame);
                    const spriteSource = frameCvs || cachedSpriteImages[spkType];

                    if (spriteSource) {
                        const drawSingle = (targetCtx) => {
                            if (frameCvs) {
                                targetCtx.drawImage(frameCvs, 0, 0, frameCvs.width, frameCvs.height, dx, dy, dw, dh);
                            } else {
                                const srcW = (spriteSource.naturalWidth || 2048) / cols;
                                const srcH = (spriteSource.naturalHeight || 1536) / rows;
                                targetCtx.drawImage(spriteSource, col * srcW, row * srcH, srcW, srcH, dx, dy, dw, dh);
                            }
                        };

                        // Bloom Layer
                        if (sparkleKeySettings.bloomEnabled && (sparkleKeySettings.bloomStrength || 0) > 0 && (sparkleKeySettings.bloomOpacity || 0) > 0) {
                            bCtx.save();
                            const bloomCanvasBlendModes = {
                                'normal': 'source-over',
                                'screen': 'screen',
                                'addition': 'lighter',
                                'lighter': 'lighter',
                                'overlay': 'overlay',
                                'soft_light': 'soft-light',
                                'hard_light': 'hard-light',
                                'color_dodge': 'color-dodge',
                                'dodge': 'color-dodge'
                            };
                            const bMode = bloomCanvasBlendModes[sparkleKeySettings.bloomBlendMode || 'screen'] || 'screen';
                            bCtx.globalCompositeOperation = bMode;

                            const blurScale = drawParams.dstW / 1200;
                            const blurRadius = (sparkleKeySettings.bloomRadius || 15) * blurScale * (sparkleKeySettings.bloomStrength || 1.2);
                            bCtx.shadowColor = sparkleKeySettings.bloomColor || '#ffffff';
                            bCtx.shadowBlur = blurRadius;
                            const bAlpha = (sparkleKeySettings.bloomOpacity !== undefined ? sparkleKeySettings.bloomOpacity : 1.0) * opacityMax;
                            bCtx.globalAlpha = Math.max(0.0, Math.min(1.0, bAlpha));
                            drawSingle(bCtx);
                            bCtx.restore();
                        }

                        // Core frame
                        bCtx.save();
                        bCtx.globalCompositeOperation = currentSparkleBlend;
                        bCtx.globalAlpha = opacityMax;
                        drawSingle(bCtx);
                        bCtx.restore();
                    }
                    return;
                }

                // Statyczny błysk
                if (!s.should_appear) return;
                
                let speedAdjustedFadeIn = fadeIn;
                let speedAdjustedHold = hold;
                let speedAdjustedFadeOut = fadeOut;
                let speedAdjustedGap = s.gap_duration;
                if (enableBlinking && blinkingSpeed !== 1.0) {
                    speedAdjustedFadeIn = Math.max(1, Math.floor(fadeIn / blinkingSpeed));
                    speedAdjustedHold = Math.max(1, Math.floor(hold / blinkingSpeed));
                    speedAdjustedFadeOut = Math.max(1, Math.floor(fadeOut / blinkingSpeed));
                    speedAdjustedGap = Math.max(0, Math.floor(s.gap_duration / blinkingSpeed));
                }
                const speedAdjustedTotalCycle = speedAdjustedFadeIn + speedAdjustedHold + speedAdjustedFadeOut;
                
                let alpha = 0.0;
                if (s.timing_mode === 'manual') {
                    if (curFrame < s.start_frame || curFrame > s.end_frame) return;
                    
                    let spFadeIn = speedAdjustedFadeIn;
                    let spFadeOut = speedAdjustedFadeOut;
                    const durationFrames = s.end_frame - s.start_frame;
                    if (spFadeIn + spFadeOut > durationFrames) {
                        const ratio = durationFrames / (spFadeIn + spFadeOut);
                        spFadeIn = Math.floor(spFadeIn * ratio);
                        spFadeOut = Math.floor(spFadeOut * ratio);
                    }
                    
                    if (curFrame - s.start_frame < spFadeIn) {
                        alpha = (curFrame - s.start_frame) / Math.max(1, spFadeIn);
                    } else if (s.end_frame - curFrame < spFadeOut) {
                        alpha = (s.end_frame - curFrame) / Math.max(1, spFadeOut);
                    } else {
                        alpha = 1.0;
                        if (jitterAmount > 0.001) {
                            const jitterVal = Math.sin(s.frame_offset + curFrame * 0.3) * (jitterAmount * 0.5);
                            alpha = Math.max(1.0 - (jitterAmount * 0.5), Math.min(1.0, 1.0 + jitterVal));
                        }
                    }
                } else {
                    if (!enableBlinking) {
                        alpha = 1.0;
                        if (jitterAmount > 0.001) {
                            const jitterVal = Math.sin(s.frame_offset + curFrame * 0.3) * (jitterAmount * 0.5);
                            alpha = Math.max(1.0 - (jitterAmount * 0.5), Math.min(1.0, 1.0 + jitterVal));
                        }
                    } else {
                        const cycleFrame = (curFrame + s.frame_offset) % (speedAdjustedTotalCycle + speedAdjustedGap);
                        if (cycleFrame < speedAdjustedFadeIn) {
                            alpha = cycleFrame / speedAdjustedFadeIn;
                        } else if (cycleFrame < speedAdjustedFadeIn + speedAdjustedHold) {
                            alpha = 1.0;
                            if (jitterAmount > 0.001) {
                                const jitterVal = Math.sin(s.frame_offset + curFrame * 0.3) * (jitterAmount * 0.5);
                                alpha = Math.max(1.0 - (jitterAmount * 0.5), Math.min(1.0, 1.0 + jitterVal));
                            }
                        } else if (cycleFrame < speedAdjustedFadeIn + speedAdjustedHold + speedAdjustedFadeOut) {
                            alpha = 1.0 - (cycleFrame - (speedAdjustedFadeIn + speedAdjustedHold)) / speedAdjustedFadeOut;
                        }
                    }
                }
                
                if (alpha > 0.01) {
                    const basePixelSize = getSparkleSize(s, drawParams.dstW);
                    let currentSize = basePixelSize * alpha;
                    
                    if (sparkleSizeSmoothCheckbox && sparkleSizeSmoothCheckbox.checked && s.prev_size > 0) {
                        currentSize = s.prev_size * 0.7 + currentSize * 0.3;
                    }
                    s.prev_size = currentSize;
                    
                    if (currentSize > 0 && sparkleImg && (sparkleImg.complete || sparkleImg.naturalWidth > 0)) {
                        const renderSparkleX = drawParams.dstX + (s.x / state.sourceWidth) * drawParams.dstW;
                        const renderSparkleY = drawParams.dstY + (s.y / state.sourceHeight) * drawParams.dstH;
                        const renderSparkleSize = currentSize;
                        const dx = renderSparkleX - renderSparkleSize / 2;
                        const dy = renderSparkleY - renderSparkleSize / 2;
                        const dw = renderSparkleSize;
                        const dh = renderSparkleSize;

                        // Bloom Layer
                        if (sparkleKeySettings.bloomEnabled && (sparkleKeySettings.bloomStrength || 0) > 0 && (sparkleKeySettings.bloomOpacity || 0) > 0) {
                            bCtx.save();
                            const bloomCanvasBlendModes = {
                                'normal': 'source-over',
                                'screen': 'screen',
                                'addition': 'lighter',
                                'lighter': 'lighter',
                                'overlay': 'overlay',
                                'soft_light': 'soft-light',
                                'hard_light': 'hard-light',
                                'color_dodge': 'color-dodge',
                                'dodge': 'color-dodge'
                            };
                            const bMode = bloomCanvasBlendModes[sparkleKeySettings.bloomBlendMode || 'screen'] || 'screen';
                            bCtx.globalCompositeOperation = bMode;

                            const blurScale = drawParams.dstW / 1200;
                            const blurRadius = (sparkleKeySettings.bloomRadius || 15) * blurScale * (sparkleKeySettings.bloomStrength || 1.2);
                            bCtx.shadowColor = sparkleKeySettings.bloomColor || '#ffffff';
                            bCtx.shadowBlur = blurRadius;
                            const bAlpha = (sparkleKeySettings.bloomOpacity !== undefined ? sparkleKeySettings.bloomOpacity : 1.0) * alpha * opacityMax;
                            bCtx.globalAlpha = Math.max(0.0, Math.min(1.0, bAlpha));
                            bCtx.drawImage(sparkleImg, dx, dy, dw, dh);
                            bCtx.restore();
                        }

                        // Core frame
                        bCtx.save();
                        bCtx.globalCompositeOperation = currentSparkleBlend;
                        bCtx.globalAlpha = alpha * opacityMax;
                        bCtx.drawImage(sparkleImg, dx, dy, dw, dh);
                        bCtx.restore();
                    }
                }
            });
            bCtx.restore();
        }

        // Atomowy transfer wyrenderowanej klatki z bufora na canvas nagrywający MediaRecorder
        ctx.drawImage(backBufferCanvas, 0, 0);
        if (streamTrack && typeof streamTrack.requestFrame === 'function') {
            try { streamTrack.requestFrame(); } catch(e) {}
        }
    };

    // ========================================================
    // WYKONYWANIE NAGRANIA: WIDEO (PŁYNNE PLAYBACK) VS OBRAZ (PRECYZYJNA PĘTLA)
    // ========================================================
    if (state.isVideo && previewVideo) {
        // Zapewnij gotowość dekodera wideo
        if (previewVideo.readyState < 2) {
            await new Promise(res => {
                const onReady = () => {
                    previewVideo.removeEventListener('loadeddata', onReady);
                    previewVideo.removeEventListener('canplay', onReady);
                    res();
                };
                previewVideo.addEventListener('loadeddata', onReady, { once: true });
                previewVideo.addEventListener('canplay', onReady, { once: true });
                setTimeout(res, 800);
            });
        }

        previewVideo.pause();
        if (Math.abs(previewVideo.currentTime) > 0.03) {
            previewVideo.currentTime = 0;
            await new Promise(r => {
                const onSeek = () => { previewVideo.removeEventListener('seeked', onSeek); r(); };
                previewVideo.addEventListener('seeked', onSeek, { once: true });
                setTimeout(r, 250);
            });
        }

        renderCompositeFrame(0);
        recorder.start(250);
        logMessage("Renderowanie płynnego wideo...", "info");

        try {
            await previewVideo.play();
        } catch(playErr) {
            console.warn("Autoplay warning:", playErr);
        }

        const exportStartTime = performance.now();
        let videoRafId = null;

        const videoStep = () => {
            if (!state.activeGeneration) {
                previewVideo.pause();
                if (recorder && recorder.state === 'recording') recorder.stop();
                return;
            }

            const now = performance.now();
            const elapsedSec = (now - exportStartTime) / 1000;
            const curFrame = Math.round(elapsedSec * fps);

            if (elapsedSec >= duration || curFrame >= totalFrames) {
                previewVideo.pause();
                logMessage("Finalizowanie wideo...", "info");
                setTimeout(() => {
                    if (recorder && recorder.state === 'recording') {
                        try { recorder.requestData(); } catch(e) {}
                        setTimeout(() => {
                            if (recorder && recorder.state === 'recording') recorder.stop();
                        }, 150);
                    }
                }, 200);
                return;
            }

            // Płynne zapętlenie wideo jeśli docelowy czas jest dłuższy niż plik źródłowy
            if (isFinite(previewVideo.duration) && previewVideo.duration > 0 && previewVideo.currentTime >= previewVideo.duration - 0.05) {
                previewVideo.currentTime = 0;
            }

            renderCompositeFrame(curFrame);

            // Aktualizacja paska postępu
            const pct = Math.min(100, (elapsedSec / duration) * 100);
            progressBar.style.width = `${pct}%`;
            progressText.textContent = `${Math.round(pct)}%`;
            if (curFrame % Math.max(1, Math.floor(totalFrames / 10)) === 0) {
                logMessage(`⏳ Renderowanie płynnego wideo: ${pct.toFixed(0)}% (${curFrame}/${totalFrames})`, 'info');
            }

            videoRafId = requestAnimationFrame(videoStep);
        };

        videoRafId = requestAnimationFrame(videoStep);
    } else {
        // OBRAZ STATYCZNY - Samokorygująca pętla klatek z zegarem o wysokiej precyzji
        renderCompositeFrame(0);
        recorder.start(250);
        logMessage("Renderowanie klatek animacji...", "info");

        let frameIdx = 0;
        const imageStartTime = performance.now();

        const imageStep = () => {
            if (!state.activeGeneration) {
                if (recorder && recorder.state === 'recording') recorder.stop();
                return;
            }

            if (frameIdx >= totalFrames) {
                logMessage("Finalizowanie wideo...", "info");
                setTimeout(() => {
                    if (recorder && recorder.state === 'recording') {
                        try { recorder.requestData(); } catch(e) {}
                        setTimeout(() => {
                            if (recorder && recorder.state === 'recording') recorder.stop();
                        }, 150);
                    }
                }, 200);
                return;
            }

            renderCompositeFrame(frameIdx);
            frameIdx++;

            const pct = (frameIdx / totalFrames) * 100;
            progressBar.style.width = `${pct}%`;
            progressText.textContent = `${Math.round(pct)}%`;
            if (frameIdx % Math.max(1, Math.floor(totalFrames / 10)) === 0 || frameIdx === totalFrames) {
                logMessage(`⏳ Renderowanie klatek: ${pct.toFixed(0)}% (${frameIdx}/${totalFrames})`, 'info');
            }

            const targetMs = frameIdx * frameDuration;
            const currentMs = performance.now() - imageStartTime;
            const delay = Math.max(0, targetMs - currentMs);
            setTimeout(imageStep, delay);
        };

        imageStep();
    }
}
